dding:clamp(18px,3vw,30px);box-shadow:0 15px 40px #142b4d0a}.doc-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:clamp(20px,3vw,34px);align-items:start}.doc-title{display:flex;align-items:center;gap:13px}.doc-icon{width:54px;height:54px;flex:0 0 54px;display:grid;place-items:center;border-radius:15px;background:#fff0f0;color:#d92525;font-size:25px}.doc-desc{color:#66748a;line-height:1.9;margin:20px 0}.download{display:inline-flex;align-items:center;gap:9px;padding:12px 18px;border-radius:10px;background:#087f8c;color:white;text-decoration:none;font-weight:700}.qrbox{text-align:center;background:#f7f9fc;border:1px solid #e5ebf3;border-radius:15px;padding:15px}.qrbox img{width:100%;max-width:175px;height:auto}.qrbox p{font-size:12px;color:#718096}.doc-info{font-size:12px;color:#8290a4;margin-top:15px}@media(max-width:760px){.wrap{width:calc(100% - 32px)}.hero{padding:30px 0}.doc-layout{grid-template-columns:1fr;gap:22px}.qrbox{max-width:280px;width:100%;margin-inline:auto}.main{padding:22px 0 42px}.doc-title{align-items:flex-start}.doc-desc{font-size:15px}.download{width:100%;justify-content:center}}@media(max-width:380px){.wrap{width:calc(100% - 24px)}.doc-card{padding:15px}.doc-title b{overflow-wrap:anywhere}}</style></head><body><?php require __DIR__.'/app/public-header.php';?><section class="hero"><div class="wrap"><div style="font-size:12px;color:#a8e5e3;font-weight:700">ASPI DOCUMENT CENTER</div><h1><?=fh($f['title'])?></h1><p><?=fh($f['category'])?></p></div></section><main class="main"><div class="wrap"><article class="doc-card"><div class="doc-layout"><div><div class="doc-title"><span class="doc-icon"><i class="fa-solid fa-file-pdf"></i></span><div><b><?=fh($f['original_name'])?></b><div class="doc-info"><?=strtoupper(pathinfo($f['original_name'],PATHINFO_EXTENSION))?> · <?=number_format((int)$f['file_size']/1024,0)?> KB · <?=number_format((int)$f['download_count'])?> ডাউনলোড</div></div></div><?php if(trim($f['description'])!==''):?><div cla